import {
  Box,
  Card,
  CardContent,
  Grid,
  Tooltip,
  Typography,
} from "@mui/material";
import React, { useRef, useEffect, useState } from "react";

const IGASolutionOptionsCard = ({ value }) => {
  //animation
  const [visibleIndices, setVisibleIndices] = useState([]);
  const cardsRef = useRef([]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = cardsRef.current.indexOf(entry.target);
            if (index !== -1 && !visibleIndices.includes(index)) {
              setVisibleIndices((prev) => [...prev, index]);
            }
          }
        });
      },
      { threshold: 0.1 }
    );

    cardsRef.current.forEach((card) => {
      if (card) {
        observer.observe(card);
      }
    });

    return () => {
      cardsRef.current.forEach((card) => {
        if (card) {
          observer.unobserve(card);
        }
      });
    };
  }, [visibleIndices]);

  return (
    <>
      <Grid container spacing={5} sx={{ py: 5 }}>
        {value?.map((item, index) => (
          <Grid
            item
            xs={12}
            md={4}
            key={index}
            // ref={(el) => (cardsRef.current[index] = el)}
            // sx={{
            //   opacity: visibleIndices.includes(index) ? 1 : 0,
            //   transform: visibleIndices.includes(index)
            //     ? "translateX(0)"
            //     : "translateX(-50px)",
            //   transition: "opacity 0.6s ease, transform 0.6s ease",
            //   transitionDelay: visibleIndices.includes(index)
            //     ? `${index * 0.3}s` // Staggered effect by index
            //     : "0s",
            // }}
          >
            <Card
              sx={{
                border: "1px solid #CDCDE0",
                borderRadius: "19px",
                boxShadow: "none",
                height: "100%",
                transition: "border-color 0.3s ease", // Smooth transition
                "&:hover": {
                  borderColor: "#602DE1", // Change the border color on hover
                },
              }}
            >
              <CardContent
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  gap: { xs: 3, sm: 4 },
                }}
              >
                {item.icon_image && (
                  <Box sx={{ height: "44px", width: "44px" }}>
                    <img
                      src={item.icon_image}
                      style={{ height: "44px", width: "44px" }}
                    />
                  </Box>
                )}

                <Typography
                  sx={{
                    fontSize: { xs: "20px", md: "20px", lg: "24px" },
                    lineHeight: "24px",
                    fontWeight: 500,
                    color: "#201D28",
                    wordBreak: "break-word",
                    whiteSpace: "normal",
                  }}
                >
                  {item.title}
                </Typography>
                <Typography
                  sx={{
                    fontSize: { xs: "14px", sm: "18px" },
                    lineHeight: { xs: "22px", sm: "30px" },
                    fontWeight: 500,
                    color: "#646271",
                    wordBreak: "break-word",
                    whiteSpace: "normal",
                  }}
                >
                  {/* {item.description.length > 210 ? (
                    <Tooltip
                      title={
                        <div
                          dangerouslySetInnerHTML={{ __html: item.description }}
                        />
                      }
                      arrow
                    >
                      <div
                        dangerouslySetInnerHTML={{
                          __html: `<style>p { margin: 0; }</style>${item.description.slice(
                            0,
                            210
                          )}...`,
                        }}
                      />
                    </Tooltip>
                  ) : (
                    <div
                      dangerouslySetInnerHTML={{
                        __html: `<style>p { margin: 0; }</style>${item.description}`,
                      }}
                    />
                  )} */}
                  <div
                    dangerouslySetInnerHTML={{
                      __html: `<style>p { margin: 0; }</style>${item.description}`,
                    }}
                  />
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </>
  );
};

export default IGASolutionOptionsCard;
