import {
  Box,
  Button,
  Card,
  CardContent,
  Container,
  Grid,
  Typography,
} from "@mui/material";
import React from "react";
import checkIcon from "../../../../assets/images/Checkicon.svg";
import ScrollAnimation from "react-animate-on-scroll";
import { Link, useParams } from "react-router-dom";
import { toastError } from "src/utils/utils";
import { useEffect } from "react";
import { ApiEndpoints } from "src/network/endpoints";
import { axiosInstance } from "src/network/adapter";
import { useState } from "react";
import FallbackSpinner from "src/@core/components/spinner";
import { useDispatch } from "react-redux";
import { setOverviewPlanData } from "../../../../redux/reducer";

const OverviewImages = () => {
  const [overviewImages, setOverviewImages] = useState([]);
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();

  const fetchOverviewImages = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_IMAGES.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        setOverviewImages(responseData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchOverviewImages();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Container
        maxWidth={"xl"}
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 20 },
          display: "flex",
          flexDirection: "column",
          gap: 10,
        }}
      >
        {overviewImages.map((item, index) => (
          <Box key={index} sx={{ width: "100%" }}>
            <img
              src={item.image_url}
              style={{
                width: "100%",
                borderRadius: "10px",
                height: "100%",
                maxHeight: "800px",
              }}
            />
          </Box>
        ))}
        {/* {overviewImages.map((item, index) => (
          <Box key={index} sx={{ width: "100%", height: "auto" }}>
            <img
              src={item.image_url}
              style={{
                width: "100%", // Make the image take up the full width of the container
                height: "auto", // Adjust the height to maintain the aspect ratio
                borderRadius: "10px",
                objectFit: "contain", // Ensure the whole image is visible without cropping
                maxHeight: "400px", // Limit the height if necessary to prevent the image from becoming too large
                display: "block", // Prevents unwanted space below the image
              }}
            />
          </Box>
        ))} */}
      </Container>
    </>
  );
};

export default OverviewImages;
